// SECRET-FREE health monitor. No app secret anywhere (we cannot obtain it).
// FB/IG page tokens derived from a long-lived user token never expire -> we only check LIVENESS
// via GET /me (200+id = alive, code 190 = dead -> re-mint in browser). Threads rotates (th_refresh_token,
// no secret required) so it gets a real refresh + credential PATCH.
if (!$env.MKT_FB_PAGE_ACCESS_TOKEN) throw new Error('mkt_meta_refresh: missing MKT_FB_PAGE_ACCESS_TOKEN');
const hasThreads = !!($env.MKT_THREADS_ACCESS_TOKEN && $env.MKT_THREADS_CREDENTIAL_ID && $env.N8N_API_KEY);
const hasIg = !!($env.MKT_IG_ACCESS_TOKEN && $env.MKT_IG_USER_ID);
return [{ json: { jobId: crypto.randomUUID(), startedAt: new Date().toISOString(), hasThreads, hasIg, fbTokenLength: $env.MKT_FB_PAGE_ACCESS_TOKEN.length } }];

// GET /me on a page token returns { id, name } when alive, or { error:{code:190,...} } when dead.
const r = $json || {};
const err = r.error || null;
const alive = !!r.id && !err;
let reason = null;
if (err) reason = (err.code === 190 ? 'expired_or_revoked' : (err.message || 'error')) + (err.error_subcode ? ` (subcode ${err.error_subcode})` : '');
return [{ json: { fbAlive: alive, fbName: r.name || null, fbNeedsAttention: !alive, fbError: err ? (err.message || String(err)) : null, fbReason: reason } }];

const r = $json || {};
const err = r.error || null;
const alive = !!r.id && !err;
let reason = null;
if (err) reason = (err.code === 190 ? 'expired_or_revoked' : (err.message || 'error')) + (err.error_subcode ? ` (subcode ${err.error_subcode})` : '');
return [{ json: { igAlive: alive, igUsername: r.username || null, igNeedsAttention: !alive, igError: err ? (err.message || String(err)) : null, igReason: reason } }];
